# blender -b -P tools/export_npcs.py -- extract/ue/npcs/lista.json
#
# Exports each NPC (nwbt glb) as extract/ue/npcs/<SK_name>/<SK_name>.fbx (mesh + skeleton, no animation) and
# writes materials.json (material -> PNG channels) next to it, in the export_ue.py / import_nw.py format.
# List: [{"glb": "...", "mesh": "SK_<name>", "cdf": "<extracted .cdf>"}], generated by tools/convert_npcs.py.
#
# The NPCs' .cdf is a template with every attachment filled (bare male body in shirt1, goatee, helmet);
# the game hides those with Flags="1" (CryEngine: hidden). Only the visible skin attachments stay. shirt2 is the
# torso clothing here (for the player nwchar drops shirt2).
import json
import os
import sys
import xml.etree.ElementTree as ET

import bpy

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import nwchar  # noqa: E402

list_path = sys.argv[sys.argv.index("--") + 1]
root = os.path.dirname(list_path)
for item in json.load(open(list_path)):
    out = os.path.join(root, item["mesh"])
    os.makedirs(out, exist_ok=True)
    bpy.ops.wm.read_factory_settings(use_empty=True)
    hidden = {a.get("AName") for a in ET.parse(item["cdf"]).getroot().iter("Attachment")
              if a.get("Type") == "CA_SKIN" and int(a.get("Flags") or 0) & 1}
    arm = nwchar.import_character(item["glb"], drop={"xray", "Icosphere"} | hidden)
    arm.name = "Armature"  # Unreal drops the armature object as root bone only with this name
    meshes = [o for o in bpy.context.scene.objects if o.type == "MESH" and o.parent == arm]
    nwchar.to_centimeters(arm, meshes)
    materials = nwchar.flatten_materials(os.path.join(out, "textures"))
    arm.animation_data_clear()
    bpy.ops.object.select_all(action="DESELECT")
    for o in [arm] + meshes:
        o.select_set(True)
    bpy.context.view_layer.objects.active = arm
    bpy.ops.export_scene.fbx(filepath=os.path.join(out, item["mesh"] + ".fbx"), use_selection=True,
                             object_types={"ARMATURE", "MESH"}, bake_anim=False, path_mode="COPY",
                             embed_textures=True, add_leaf_bones=False, apply_unit_scale=True,
                             apply_scale_options="FBX_SCALE_NONE", mesh_smooth_type="FACE",
                             use_armature_deform_only=False)
    json.dump(materials, open(os.path.join(out, "materials.json"), "w"), indent=1)
    print(f"NPC {item['mesh']}: {len(meshes)} meshes, {len(materials)} materials")
